update pages set contenu = '{"sections":[]}'::jsonb where path = '/entreprise-maintenance-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Entreprise de maintenance industrielle","mecanisme":"Vous comparez des prestataires, et tous promettent la même chose. Migen est une entreprise de maintenance industrielle présente partout en France. Nous écrivons ce que les autres laissent vide : qui intervient, en combien de temps on vous rappelle, et ce qui figure sur le devis.","cta":"Parler à un chargé d''affaires","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en dehors de ces horaires."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers","detail":"Le renouvellement est la seule preuve qui compte."},{"valeur":"10 %","libelle":"des candidats retenus, après un entretien technique ET un entretien comportemental."},{"valeur":"+ 100","libelle":"collaborateurs salariés, 4 agences, Lyon (siège), Montréal, Dubaï et Madrid."}]},{"type":"probleme","punchline":"La ligne est arrêtée un vendredi à 16h00. Vous appelez trois numéros. Deux répondent lundi, le troisième envoie quelqu''un qui voit la machine pour la première fois.","puces":[{"accroche":"Le diagnostic raté immobilise deux jours de plus.","texte":"Le technicien ne connaît ni le process, ni l''historique, ni l''automate. Il cherche, et vous payez pendant qu''il cherche."},{"accroche":"Personne ne remonte à la cause racine.","texte":"On change la pièce, on redémarre, et la même panne revient six semaines plus tard, au même endroit."},{"accroche":"L''interlocuteur change à chaque visite.","texte":"Aucune mémoire du parc, aucun compte rendu exploitable, un dossier machine qui reste vide."},{"accroche":"Le préventif recule d''un cran à chaque urgence.","texte":"Le retard s''accumule dans la GMAO et le budget bascule intégralement du côté correctif."},{"accroche":"La facture se négocie machine à l''arrêt.","texte":"C''est le pire moment possible pour discuter d''un tarif, et tout le monde le sait."}]}]'::jsonb) where path = '/entreprise-maintenance-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"Un technicien présent chaque jour dans vos murs","texte":", intégré à votre équipe de production. Voir la [sous-traitance maintenance](/offres/residence/)."},"benefice":"Le poste est tenu sans recrutement, et remplacé s''il s''arrête. Vous gardez la production, nous portons la ressource."},{"prestation":{"accroche":"Un contrat de visites préventives planifiées","texte":", avec suivi de l''état du parc et priorité d''intervention. Voir le [contrat de maintenance](/offres/zero-arret/)."},"benefice":"Votre budget devient une ligne connue d''avance au lieu d''une série de factures subies. Diagnostic gratuit pour démarrer."},{"prestation":{"accroche":"Une intervention ponctuelle sur la panne","texte":", partout en France, sans contrat préalable. Voir le [dépannage industriel](/offres/depannage-industriel/)."},"benefice":"Une panne, une intervention, une facture. Personne ne vous impose un abonnement pour être dépanné."},{"prestation":{"accroche":"Une astreinte 24/24 et 7/7","texte":", nuits, week-ends et jours fériés. Voir l''[astreinte industrielle](/offres/depannage-industriel/astreinte/)."},"benefice":"Un numéro qui décroche quand la ligne tombe à 2h00 du matin, avec un technicien déjà briefé sur votre site."},{"prestation":{"accroche":"La préparation et l''exécution de vos arrêts planifiés","texte":", coordination des corps de métier comprise. Voir l''[arrêt technique maintenance](/offres/arret-technique/)."},"benefice":"La date de redémarrage tient, parce que le programme a été arbitré avant la première consignation."},{"prestation":{"accroche":"La remise à niveau de machines anciennes","texte":", mécanique, électrique, automatisme. Voir le [retrofit machine industrielle](/offres/retrofit/)."},"benefice":"Une machine qui repart pour dix ans coûte moins cher qu''une machine neuve, et elle garde vos réglages."}],"prose":[{"texte":"Une entreprise de maintenance industrielle ne devrait pas vous vendre son catalogue. Elle devrait partir de votre situation, puis proposer la formule la moins chère qui règle le problème. Avant de choisir, notre [guide pour choisir une entreprise de maintenance](/guides/choisir-une-entreprise-de-maintenance/) liste les questions à poser en rendez-vous."},{"texte":"Nos six modalités de travail répondent chacune à un moment différent de la vie de votre parc. Vous n''avez pas à choisir avant d''appeler : nous vous orientons."},{"texte":"Une panne engage rarement un seul métier, qu''elle relève de la maintenance préventive ou de la maintenance curative. La vraie question est de savoir qui vient en appui quand le premier technicien bute."}]}]'::jsonb) where path = '/entreprise-maintenance-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"4 champs et un choix d''intention dans le formulaire, ou un appel direct. Vous n''avez pas besoin de savoir quelle offre vous convient."},{"titre":"Rappel dans l''heure","texte":"un chargé d''affaires qualifie le besoin au téléphone, équipement par équipement, et vous dit ce qui est faisable. Aux horaires ouvrés, lundi au vendredi 8h00 à 18h30."},{"titre":"Orientation vers la formule la plus économique","texte":"si une intervention ponctuelle suffit, nous ne vendons pas un contrat annuel. Si le contrat coûte moins cher sur l''année, nous le démontrons calcul à l''appui."},{"titre":"Devis détaillé poste par poste","texte":"périmètre, contenu, exclusions, montant. Un document qui se lit sans avocat, et qui se compare ligne à ligne avec celui d''un concurrent."},{"titre":"Affectation d''un technicien évalué","texte":"le profil est choisi sur vos machines et votre secteur, pas sur la disponibilité du moment. Les résultats de son évaluation vous sont présentés."},{"titre":"Compte rendu après chaque passage","texte":"cause, travaux réalisés, pièces posées, recommandations, au format de votre GMAO. Le dossier machine reste votre propriété."}]},{"type":"garanties","puces":[{"accroche":"Le niveau réel de qui intervient.","texte":"Évaluation technique et comportementale en entretien, 10 % des candidats retenus, résultats consultables avant que vous décidiez. Ce sont des salariés Migen, pas des inconnus recrutés pour la mission."},{"accroche":"Aucun revenu sur les pièces.","texte":"Nous ne sommes ni fabricant ni distributeur. Nous consultons le marché au prix réel, donc une recommandation de remplacement reste une recommandation technique."},{"accroche":"Votre connaissance reste chez vous.","texte":"Chaque rapport est édité et archivé dans le dossier de la machine, plans et schémas compris, même le jour où vous changez de prestataire."}]},{"type":"cta","question":"Besoin de savoir quelle formule coûte le moins cher pour votre site ?","bouton":"Faire chiffrer mon besoin","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Nous vous rappelons dans l''heure. En dehors, l''astreinte 24/24 et 7/7 prend le relais."}]'::jsonb) where path = '/entreprise-maintenance-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Maintenance préventive annuelle sur des centres logistiques","texte":"six techniciens polyvalents en permanence, depuis septembre 2023","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Maintenance préventive et curative d''une fonderie, 7 jours sur 7, automobile","texte":"six techniciens en poste depuis octobre 2023, aux côtés des équipes internes","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Renfort continu en 3x8 sur des lignes de nutrition infantile, agroalimentaire","texte":"deux techniciens intégrés aux équipes du site de Steenvoorde","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Accompagnement d''une montée en cadence sur plusieurs usines, automobile","texte":"trois à cinq techniciens déployés depuis septembre 2024","lienLibelle":"Étude de cas VALEO : plusieurs usines","lienHref":"/preuves/valeo-usines/"},{"titre":"Installation et mise en production d''un parc machine neuf, automobile","texte":"six techniciens constitués en équipe dédiée depuis janvier 2023","lienLibelle":"Étude de cas EATON : mise en production","lienHref":"/preuves/eaton-mise-en-production/"},{"titre":"Remise en état d''un site à risque chimique, traitement des eaux","texte":"renfort habilité, depuis février 2026","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"}]}]'::jsonb) where path = '/entreprise-maintenance-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Combien coûte une prestation de maintenance industrielle ?","reponse":"Le chiffrage se fait après qualification du besoin, avec une visite quand le périmètre le justifie. Sur un parc industriel, la maintenance planifiée et le dépannage subi n''ont pas le même prix de revient. Nous vous montrons les deux. Le taux horaire est homogène dans toute la France, sans surfacturation régionale. Le devis détaille chaque poste, et nous cherchons la prestation la plus économique pour votre situation, pas la plus grosse ligne de commande."},{"question":"Faut-il s''engager pour travailler avec vous ?","reponse":"Non pour une intervention ponctuelle : une panne, une intervention, une facture. Le contrat Zéro arrêt est le seul format engageant, avec un engagement type de 6 mois renouvelable, écrit en clair. Assez long pour produire des résultats mesurables, assez court pour que nous ayons à les prouver."},{"question":"Nous avons déjà une société de maintenance industrielle sous contrat. Comment se passe la reprise ?","reponse":"Nous reprenons le périmètre tel qu''il est écrit : inventaire du parc, récupération des historiques, reprise du plan de visites, puis ajustement. La bascule se prépare pendant le préavis de votre contrat en cours. Nous ne demandons jamais de résilier avant d''avoir un programme écrit et validé."},{"question":"Qui vient réellement sur notre site ?","reponse":"Des techniciens salariés de Migen, évalués en entretien sur la technique et sur le comportement. Seuls 10 % des candidats sont retenus, et les résultats de ces évaluations vous sont présentés avant votre décision. Les profils vont du bac pro maintenance au diplôme d''ingénieur, avec des spécialistes automatisme et robotique."},{"question":"Et la sécurité sur nos installations ?","reponse":"Plan de prévention, accueil sécurité du site, habilitations à jour, équipements de protection, respect des procédures de consignation : c''est un préalable, pas une case à cocher. Migen est l''employeur et porte la formation, le suivi médical et les attestations de vigilance. Nos comptes rendus sont conçus pour tenir dans un système qualité."},{"question":"Couvrez-vous notre région ?","reponse":"Oui, partout en France, depuis Lyon où se trouve notre siège, complété par nos hubs de techniciens dans les grandes villes. La grande majorité des interventions est réalisée par des techniciens du bassin concerné. Cela compte pour les temps de trajet, et pour la connaissance du tissu industriel local. Nous intervenons aussi hors de France : notre premier contrat belge a démarré en octobre 2024, [Étude de cas McCAIN : Belgique](/preuves/mccain-belgique/)."}]},{"type":"ctaFinal","question":"Besoin d''un interlocuteur qui vous dise honnêtement de quoi votre site a besoin ?","bouton":"Demander une intervention","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés, astreinte 24/24 et 7/7 en dehors."}]'::jsonb) where path = '/entreprise-maintenance-industrielle/';
